--
-- Structure for view `v_service_requests_full`
--
DROP TABLE IF EXISTS `v_service_requests_full`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY INVOKER VIEW `v_service_requests_full`  AS SELECT `r`.`request_id` AS `request_id`, `r`.`user_id` AS `user_id`, `r`.`request_code` AS `request_code`, `r`.`service_code` AS `service_code`, `r`.`service_name` AS `service_name`, `r`.`requester_prefix_id` AS `requester_prefix_id`, `r`.`requester_name` AS `requester_name`, `r`.`requester_position` AS `requester_position`, `r`.`requester_phone` AS `requester_phone`, `r`.`requester_email` AS `requester_email`, `r`.`department_id` AS `department_id`, `r`.`department_name` AS `department_name`, `r`.`subject` AS `subject`, `r`.`description` AS `description`, `r`.`request_data` AS `request_data`, `r`.`status` AS `status`, `r`.`priority` AS `priority`, `r`.`assigned_to` AS `assigned_to`, `r`.`assigned_at` AS `assigned_at`, `r`.`admin_notes` AS `admin_notes`, `r`.`rejection_reason` AS `rejection_reason`, `r`.`completion_notes` AS `completion_notes`, `r`.`expected_completion_date` AS `expected_completion_date`, `r`.`started_at` AS `started_at`, `r`.`completed_at` AS `completed_at`, `r`.`cancelled_at` AS `cancelled_at`, `r`.`created_at` AS `created_at`, `r`.`updated_at` AS `updated_at`, `ms`.`icon` AS `icon`, `ms`.`color_code` AS `color_code`, `ms`.`service_name_en` AS `service_name_en`, `u`.`username` AS `username`, `d`.`department_code` AS `department_code` FROM (((`service_requests` `r` left join `my_service` `ms` on(`r`.`service_code` = `ms`.`service_code`)) left join `users` `u` on(`r`.`user_id` = `u`.`user_id`)) left join `departments` `d` on(`r`.`department_id` = `d`.`department_id`)) ;

