--
-- Structure for view `v_task_assignments`
--
DROP TABLE IF EXISTS `v_task_assignments`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY INVOKER VIEW `v_task_assignments`  AS SELECT `ta`.`assignment_id` AS `assignment_id`, `ta`.`request_id` AS `request_id`, `sr`.`request_code` AS `request_code`, `sr`.`service_name` AS `service_name`, `sr`.`requester_name` AS `requester_name`, `ta`.`assigned_to` AS `assigned_to`, `u_to`.`username` AS `assigned_to_username`, concat(ifnull(`p_to`.`prefix_name`,''),`u_to`.`first_name`,' ',`u_to`.`last_name`) AS `assigned_to_name`, `ta`.`assigned_as_role` AS `assigned_as_role`, `r`.`role_name` AS `assigned_role_name`, `r`.`role_icon` AS `role_icon`, `r`.`role_color` AS `role_color`, `ta`.`assigned_by` AS `assigned_by`, `u_by`.`username` AS `assigned_by_username`, concat(ifnull(`p_by`.`prefix_name`,''),`u_by`.`first_name`,' ',`u_by`.`last_name`) AS `assigned_by_name`, `ta`.`status` AS `status`, `ta`.`priority` AS `priority`, `ta`.`due_date` AS `due_date`, `ta`.`notes` AS `notes`, `ta`.`accepted_at` AS `accepted_at`, `ta`.`started_at` AS `started_at`, `ta`.`completed_at` AS `completed_at`, `ta`.`created_at` AS `created_at` FROM ((((((`task_assignments` `ta` join `service_requests` `sr` on(`ta`.`request_id` = `sr`.`request_id`)) join `users` `u_to` on(`ta`.`assigned_to` = `u_to`.`user_id`)) left join `prefixes` `p_to` on(`u_to`.`prefix_id` = `p_to`.`prefix_id`)) join `users` `u_by` on(`ta`.`assigned_by` = `u_by`.`user_id`)) left join `prefixes` `p_by` on(`u_by`.`prefix_id` = `p_by`.`prefix_id`)) left join `roles` `r` on(`ta`.`assigned_as_role` = `r`.`role_id`)) ;

