-- Structure for view `v_users_full`
--
DROP TABLE IF EXISTS `v_users_full`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY INVOKER VIEW `v_users_full`  AS SELECT `u`.`user_id` AS `user_id`, `u`.`username` AS `username`, `u`.`prefix_id` AS `prefix_id`, `p`.`prefix_name` AS `prefix_name`, `u`.`first_name` AS `first_name`, `u`.`last_name` AS `last_name`, concat(ifnull(`p`.`prefix_name`,''),' ',`u`.`first_name`,' ',`u`.`last_name`) AS `full_name`, `u`.`email` AS `email`, `u`.`phone` AS `phone`, `u`.`role` AS `role`, `u`.`status` AS `status`, `u`.`department_id` AS `department_id`, `d`.`department_name` AS `department_name`, `d`.`department_code` AS `department_code`, `u`.`position` AS `position`, `u`.`profile_image` AS `profile_image`, `u`.`line_user_id` AS `line_user_id`, `u`.`line_display_name` AS `line_display_name`, `u`.`line_picture_url` AS `line_picture_url`, `u`.`line_linked_at` AS `line_linked_at`, `u`.`last_login` AS `last_login`, `u`.`created_at` AS `created_at`, `u`.`updated_at` AS `updated_at` FROM ((`users` `u` left join `prefixes` `p` on(`u`.`prefix_id` = `p`.`prefix_id`)) left join `departments` `d` on(`u`.`department_id` = `d`.`department_id`)) ;

